// Wavelength in nm of each band
float bandWavelength(int band)
{
    return 380.0f + 10.0f * band;
}

// Weight of the red (0), green (1), or blue (2) control point at a wavelength, for paperSpectrumFromRGB
float paperWeight(int control, float wavelength)
{
    const float red = 610.0f;
    const float green = 545.0f;
    const float blue = 450.0f;
    float w = glm::clamp(wavelength, blue, red);
    if (w <= green)
    {
        float t = (w - blue) / (green - blue);
        return control == 2 ? 1.0f - t : control == 1 ? t : 0.0f;
    }
    float t = (w - green) / (red - green);
    return control == 1 ? 1.0f - t : control == 0 ? t : 0.0f;
}
// Converts thickness in the units of KubelkaMunk.h to the units of the measured K and S
// With this scale, the median thickness at which a pigment over white paper reaches half of its full color
const float thicknessScale = 1.6f;
