MeasuredPigment measuredPigmentFromName(const std::string &name)
{
    for (const NamedMeasuredPigment &entry : measuredPalette())
        if (entry.name == name)
            return entry.pigment;
    throw std::invalid_argument("Unknown measured pigment: " + name);
}

MeasuredLayer measuredLayerFromMix(const std::vector<MeasuredLayer> &parts)
{
    return kmcore::layerFromMix(parts);
}

glm::vec3 colorFromMeasuredLayers(const std::vector<MeasuredLayer> &layers, const glm::vec3 &paperColor)
{
    // Start with bare paper: it reflects its own spectrum and lets no light through
    kmcore::ReflectTransmit<MeasuredSpectrum> stack;
    stack.R = paperSpectrumFromRGB(paperColor);
    stack.T.fill(0.0f);

    // Put each layer of paint on top of everything below it
    for (const MeasuredLayer &layer : layers)
        stack = kmcore::stackLayers(kmcore::computeLayer(MeasuredLayer{layer.pigment, layer.thickness * thicknessScale}), stack);

    // The final color is the reflectance of the whole stack, converted to RGB
    return rgbFromMeasuredSpectrum(stack.R);
}

glm::vec3 rgbFromMeasuredSpectrum(const MeasuredSpectrum &spectrum)
{
    glm::vec3 rgb(0.0f);
    for (int ch = 0; ch < 3; ch++)
        for (int band = 0; band < measuredBands; band++)
            rgb[ch] += measuredSpectrumToRGB[ch][band] * spectrum[band];
    return rgb;
}

MeasuredSpectrum paperSpectrumFromRGB(const glm::vec3 &paperColor)
{
    // The spectrum is a weighted sum of the three control point shapes, so its RGB color is (A * weights),
    // where column k of A is the RGB color of control point shape k
    // Solving A * weights = paperColor gives the weights for exactly that color
    static const glm::mat3 inverseA = []
    {
        glm::mat3 A(0.0f);
        for (int control = 0; control < 3; control++)
        {
            MeasuredSpectrum shape;
            for (int band = 0; band < measuredBands; band++)
                shape[band] = paperWeight(control, bandWavelength(band));
            A[control] = rgbFromMeasuredSpectrum(shape);
        }
        return glm::inverse(A);
    }();
    glm::vec3 weights = inverseA * paperColor;

    MeasuredSpectrum spectrum;
    for (int band = 0; band < measuredBands; band++)
    {
        float w = bandWavelength(band);
        spectrum[band] = weights[0] * paperWeight(0, w) + weights[1] * paperWeight(1, w) + weights[2] * paperWeight(2, w);
    }
    return spectrum;
}
